content.content:
     1→{% comment %}
     2→  Zip Code Checker — Theme App Extension Block
     3→  Add this block to any section in the Shopify Theme Editor.
     4→  The block automatically connects to your app — no manual configuration needed.
     5→{% endcomment %}
     6→
     7→{% if request.design_mode %}
     8→  {% comment %}
     9→    Theme Editor preview — render a static placeholder so no live API calls
    10→    are made during theme customization. The real widget loads on the storefront.
    11→  {% endcomment %}
    12→  <div style="
    13→    background:#ffffff;
    14→    border:1px solid #e1e3e5;
    15→    border-radius:8px;
    16→    padding:24px;
    17→    max-width:480px;
    18→    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
    19→    box-sizing:border-box;
    20→    color:#202223;
    21→  ">
    22→    <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
    23→    <div style="display:flex;gap:8px;margin-bottom:12px;">
    24→      <input
    25→        type="text"
    26→        placeholder="Enter your zip code"
    27→        disabled
    28→        style="
    29→          flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
    30→          font-size:14px;background:#fafbfb;color:#202223;min-width:0;
    31→        "
    32→      >
    33→      <button
    34→        type="button"
    35→        disabled
    36→        style="
    37→          background:#008060;color:#fff;border:none;border-radius:8px;
    38→          padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
    39→          opacity:0.7;cursor:default;
    40→        "
    41→      >Check</button>
    42→    </div>
    43→    <div style="
    44→      background:#00806015;border-left:3px solid #008060;border-radius:8px;
    45→      padding:12px;font-size:14px;color:#008060;line-height:1.4;
    46→    ">
    47→      Great news! We deliver to your area.
    48→      <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
    49→    </div>
    50→    <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
    51→      Zip Code Checker — live widget loads on your storefront
    52→    </p>
    53→  </div>
    54→{% else %}
    55→
    56→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
    57→
    58→<div
    59→  id="zcc-widget-{{ block.id }}"
    60→  data-shop="{{ shop.permanent_domain }}"
    61→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
    62→  data-block="{{ block.id }}"
    63→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
    64→  {{ block.shopify_attributes }}
    65→></div>
    66→
    67→<script>
    68→(function () {
    69→  var ROOT_ID = "zcc-widget-{{ block.id }}";
    70→  var container = document.getElementById(ROOT_ID);
    71→  if (!container) return;
    72→
    73→  var SHOP = container.dataset.shop;
    74→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
    75→
    76→  // Try embedded config from metafield first (instant, no network needed)
    77→  var configStr = container.getAttribute("data-config");
    78→  if (configStr) {
    79→    try {
    80→      renderWidget(JSON.parse(configStr));
    81→      return;
    82→    } catch (e) {
    83→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
    84→    }
    85→  }
    86→
    87→  // Fallback: fetch config from API
    88→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    89→    .then(function (r) {
    90→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
    91→      return r.json();
    92→    })
    93→    .then(function (cfg) { renderWidget(cfg); })
    94→    .catch(function (err) {
    95→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
    96→      renderWidget({});
    97→    });
    98→
    99→  function renderWidget(cfg) {
   100→    // Merge with defaults
   101→    var D = {
   102→      position: "inline",
   103→      heading: "Check Delivery Availability",
   104→      placeholder: "Enter your zip code",
   105→      buttonText: "Check",
   106→      successMessage: "Great news! We deliver to your area.",
   107→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
   108→      notFoundMessage: "This zip code was not found in our system.",
   109→      primaryColor: "#008060",
   110→      successColor: "#008060",
   111→      errorColor: "#D72C0D",
   112→      backgroundColor: "#FFFFFF",
   113→      textColor: "#202223",
   114→      borderRadius: "8",
   115→      showEta: true,
   116→      showZone: false,
   117→      showWaitlistOnFailure: false,
   118→      customCss: "",
   119→    };
   120→    Object.keys(D).forEach(function (k) {
   121→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
   122→    });
   123→
   124→    var rad = cfg.borderRadius + "px";
   125→    var WID = "zcc-" + ROOT_ID;
   126→
   127→    if (cfg.position === "floating") {
   128→      renderFloating(cfg, WID, rad);
   129→    } else if (cfg.position === "popup") {
   130→      renderPopup(cfg, WID, rad);
   131→    } else {
   132→      renderInline(cfg, WID, rad);
   133→    }
   134→  }
   135→
   136→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
   137→  function injectCss(wid, cfg, rad) {
   138→    var css =
   139→      "#" + wid + "{" +
   140→        "background:" + cfg.backgroundColor + " !important;" +
   141→        "color:" + cfg.textColor + " !important;" +
   142→        "border-radius:" + rad + " !important;" +
   143→        "padding:24px !important;" +
   144→        "border:1px solid #e1e3e5 !important;" +
   145→        "max-width:480px;" +
   146→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
   147→        "box-sizing:border-box !important;" +
   148→      "}" +
   149→      "#" + wid + " *{box-sizing:border-box !important}" +
   150→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
   151→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
   152→      "#" + wid + " .zcc-input{" +
   153→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
   154→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
   155→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
   156→      "}" +
   157→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
   158→      "#" + wid + " .zcc-btn{" +
   159→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   160→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
   161→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
   162→      "}" +
   163→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
   164→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   165→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
   166→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
   167→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
   168→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
   169→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
   170→      "#" + wid + " .zcc-wl-input{" +
   171→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
   172→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
   173→      "}" +
   174→      "#" + wid + " .zcc-wl-btn{" +
   175→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
   176→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
   177→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
   178→      "}" +
   179→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   180→      (cfg.customCss || "");
   181→
   182→    var styleEl = document.createElement("style");
   183→    styleEl.textContent = css;
   184→    document.head.appendChild(styleEl);
   185→  }
   186→
   187→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
   188→  function buildWidgetInner(wid, cfg, btnLabel) {
   189→    return (
   190→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   191→      '<div class="zcc-row">' +
   192→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
   193→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   194→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
   195→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
   196→      "</div>" +
   197→      '<div id="' + wid + '-res"></div>'
   198→    );
   199→  }
   200→
   201→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   202→    var inp = document.getElementById(wid + "-inp");
   203→    var btn = document.getElementById(wid + "-btn");
   204→    var res = document.getElementById(wid + "-res");
   205→    var btnLabel = cfg.buttonText;
   206→    if (!inp || !btn || !res) return;
   207→
   208→    function checkZip() {
   209→      var zip = inp.value.trim();
   210→      if (!zip) { inp.focus(); return; }
   211→
   212→      btn.disabled = true;
   213→      btn.textContent = "\u2026";
   214→      res.innerHTML = "";
   215→
   216→      fetch(
   217→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   218→          "&zip=" + encodeURIComponent(zip)
   219→      )
   220→        .then(function (r) { return r.json(); })
   221→        .then(function (data) {
   222→          btn.disabled = false;
   223→          btn.textContent = btnLabel;
   224→
   225→          if (data.allowed) {
   226→            var html = '<div class="zcc-result ok">' + esc(data.message);
   227→            if (cfg.showEta && data.eta) {
   228→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   229→            }
   230→            if (cfg.showZone && data.zone) {
   231→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   232→            }
   233→            html += "</div>";
   234→            res.innerHTML = html;
   235→          } else {
   236→            var html = '<div class="zcc-result fail">' + esc(data.message);
   237→            if (cfg.showWaitlistOnFailure) {
   238→              html +=
   239→                '<div class="zcc-wl">' +
   240→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   241→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   242→                "</div>";
   243→            }
   244→            html += "</div>";
   245→            res.innerHTML = html;
   246→
   247→            if (cfg.showWaitlistOnFailure) {
   248→              var wBtn = document.getElementById(wid + "-wl-btn");
   249→              if (wBtn) {
   250→                wBtn.addEventListener("click", function () {
   251→                  var emailEl = document.getElementById(wid + "-wl-email");
   252→                  var email = emailEl ? emailEl.value.trim() : "";
   253→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   254→                  joinWaitlist(zip, email, wBtn);
   255→                });
   256→              }
   257→            }
   258→          }
   259→        })
   260→        .catch(function () {
   261→          btn.disabled = false;
   262→          btn.textContent = btnLabel;
   263→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   264→        });
   265→    }
   266→
   267→    btn.addEventListener("click", checkZip);
   268→    inp.addEventListener("keydown", function (e) {
   269→      if (e.key === "Enter") checkZip();
   270→    });
   271→  }
   272→
   273→  function joinWaitlist(zip, email, wBtn) {
   274→    wBtn.disabled = true;
   275→    wBtn.textContent = "Joining\u2026";
   276→
   277→    fetch(API_BASE + "/api/waitlist", {
   278→      method: "POST",
   279→      headers: { "Content-Type": "application/json" },
   280→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   281→    })
   282→      .then(function (r) { return r.json(); })
   283→      .then(function (data) {
   284→        var wlEl = wBtn.closest(".zcc-wl");
   285→        if (data.success) {
   286→          if (wlEl) wlEl.innerHTML =
   287→            '<p style="font-size:13px;margin:6px 0 0">' +
   288→            "\u2713 You\u2019ve been added to the waitlist!" +
   289→            "</p>";
   290→        } else {
   291→          wBtn.disabled = false;
   292→          wBtn.textContent = "Join Waitlist";
   293→        }
   294→      })
   295→      .catch(function () {
   296→        wBtn.disabled = false;
   297→        wBtn.textContent = "Join Waitlist";
   298→      });
   299→  }
   300→
   301→  // ── Inline position ─────────────────────────────────────────────────────────
   302→  function renderInline(cfg, WID, rad) {
   303→    injectCss(WID, cfg, rad);
   304→    container.id = WID;
   305→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
   306→    wireWidget(WID, cfg, API_BASE, SHOP);
   307→  }
   308→
   309→  // ── Floating position ────────────────────────────────────────────────────────
   310→  function renderFloating(cfg, WID, rad) {
   311→    // The original container becomes invisible (just an anchor)
   312→    container.style.display = "none";
   313→
   314→    injectCss(WID, cfg, rad);
   315→
   316→    // Additional styles for floating UI
   317→    var floatCss =
   318→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
   319→      "#" + WID + "-panel{" +
   320→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   321→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
   322→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
   323→      "}" +
   324→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
   325→      "#" + WID + "-panel .zcc-panel-header{" +
   326→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
   327→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
   328→      "}" +
   329→      "#" + WID + "-panel .zcc-panel-close{" +
   330→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
   331→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
   332→      "}" +
   333→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
   334→      "#" + WID + "-trigger{" +
   335→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   336→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
   337→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
   338→      "}" +
   339→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
   340→
   341→    var floatStyle = document.createElement("style");
   342→    floatStyle.textContent = floatCss;
   343→    document.head.appendChild(floatStyle);
   344→
   345→    // Build floating shell
   346→    var floatEl = document.createElement("div");
   347→    floatEl.id = WID + "-float";
   348→    floatEl.innerHTML =
   349→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
   350→        '<div class="zcc-panel-header">' +
   351→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
   352→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
   353→        '</div>' +
   354→        '<div id="' + WID + '">' +
   355→          buildWidgetInner(WID, cfg, cfg.buttonText) +
   356→        '</div>' +
   357→      '</div>' +
   358→      '<button id="' + WID + '-trigger" type="button">' +
   359→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
   360→        esc(cfg.buttonText || "Check Delivery") +
   361→      '</button>';
   362→
   363→    document.body.appendChild(floatEl);
   364→
   365→    // Wire toggle
   366→    var trigger = document.getElementById(WID + "-trigger");
   367→    var panel = document.getElementById(WID + "-panel");
   368→    var closeBtn = document.getElementById(WID + "-close");
   369→
   370→    if (trigger && panel) {
   371→      trigger.addEventListener("click", function () {
   372→        panel.classList.toggle("zcc-hidden");
   373→      });
   374→    }
   375→    if (closeBtn && panel) {
   376→      closeBtn.addEventListener("click", function () {
   377→        panel.classList.add("zcc-hidden");
   378→      });
   379→    }
   380→    // Close on outside click
   381→    document.addEventListener("click", function (e) {
   382→      if (!floatEl.contains(e.target)) {
   383→        if (panel) panel.classList.add("zcc-hidden");
   384→      }
   385→    });
   386→
   387→    wireWidget(WID, cfg, API_BASE, SHOP);
   388→  }
   389→
   390→  // ── Popup position ───────────────────────────────────────────────────────────
   391→  function renderPopup(cfg, WID, rad) {
   392→    injectCss(WID, cfg, rad);
   393→
   394→    var popupCss =
   395→      "#" + WID + "-overlay{" +
   396→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
   397→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
   398→      "}" +
   399→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
   400→      "#" + WID + "-modal{" +
   401→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   402→        "max-width:480px !important;width:100% !important;position:relative !important;" +
   403→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
   404→      "}" +
   405→      "#" + WID + "-modal .zcc-modal-close{" +
   406→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
   407→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
   408→      "}" +
   409→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
   410→      "#" + WID + "-popup-trigger{" +
   411→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   412→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
   413→        "cursor:pointer !important" +
   414→      "}" +
   415→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
   416→
   417→    var popupStyle = document.createElement("style");
   418→    popupStyle.textContent = popupCss;
   419→    document.head.appendChild(popupStyle);
   420→
   421→    // Trigger button renders in-place (inside the block)
   422→    container.innerHTML =
   423→      '<button id="' + WID + '-popup-trigger" type="button">' +
   424→        esc(cfg.heading) +
   425→      '</button>';
   426→
   427→    // Overlay + modal append to body
   428→    var overlay = document.createElement("div");
   429→    overlay.id = WID + "-overlay";
   430→    overlay.innerHTML =
   431→      '<div id="' + WID + '-modal">' +
   432→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
   433→        '<div id="' + WID + '">' +
   434→          buildWidgetInner(WID, cfg, cfg.buttonText) +
   435→        '</div>' +
   436→      '</div>';
   437→    document.body.appendChild(overlay);
   438→
   439→    var trigger = document.getElementById(WID + "-popup-trigger");
   440→    var closeBtn = document.getElementById(WID + "-modal-close");
   441→    var modal = document.getElementById(WID + "-modal");
   442→
   443→    function openPopup() { overlay.classList.add("zcc-open"); }
   444→    function closePopup() { overlay.classList.remove("zcc-open"); }
   445→
   446→    if (trigger) trigger.addEventListener("click", openPopup);
   447→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
   448→
   449→    // Close on overlay backdrop click (not modal content)
   450→    overlay.addEventListener("click", function (e) {
   451→      if (e.target === overlay) closePopup();
   452→    });
   453→
   454→    // Close on Escape key
   455→    document.addEventListener("keydown", function (e) {
   456→      if (e.key === "Escape") closePopup();
   457→    });
   458→
   459→    wireWidget(WID, cfg, API_BASE, SHOP);
   460→  }
   461→
   462→  function esc(str) {
   463→    return String(str)
   464→      .replace(/&/g, "&amp;")
   465→      .replace(/</g, "&lt;")
   466→      .replace(/>/g, "&gt;")
